def main():
 ap=argparse.ArgumentParser();ap.add_argument('--addendum',type=Path,default=Path('specs/recurrent_parallel_appworld_signal_contended_execution_v1.json'));ap.add_argument('--addendum-lock',type=Path,default=Path('results/recurrent_parallel_appworld_signal_anchor/contended_execution_lock.json'));ap.add_argument('--raw',type=Path,default=Path('results/recurrent_parallel_appworld_signal_anchor/raw_model_outputs.json'));ap.add_argument('--parent-analysis',type=Path,default=Path('results/recurrent_parallel_appworld_signal_anchor/analysis.json'));ap.add_argument('--output-dir',type=Path,default=Path('results/recurrent_parallel_appworld_signal_anchor'));a=ap.parse_args();apath,lockp,rp,parentp=map(R,(a.addendum,a.addendum_lock,a.raw,a.parent_analysis));add=json.loads(apath.read_text());raw=json.loads(rp.read_text());parent=json.loads(parentp.read_text());_,lock_checks=verify_addendum_lock(lockp);checks={'addendum_frozen':add['status']=='FROZEN_BEFORE_MODEL_OUTCOMES','execution_lock_files':all(lock_checks.values()),'raw_complete':raw['status']=='RPD_APPWORLD_A3_RAW_COMPLETE','raw_addendum_hash':raw.get('execution_addendum_sha256')==H(apath),'raw_contended_lock_hash':raw.get('contended_execution_lock_sha256')==H(lockp),'contended_recorded':raw.get('generation',{}).get('contended') is True,'memory_cap':raw.get('generation',{}).get('memory_fraction_cap')==add['memory_fraction_cap'],'external_pid_survival':raw.get('generation',{}).get('preexisting_pid_survival') is True,'latency_excluded':raw.get('generation',{}).get('latency_authoritative') is False and add['latency_authoritative'] is False,'parent_analysis_bound':parent.get('raw_sha256')==H(rp),'parent_integrity':all(parent.get('integrity',{}).values()),'quality_status':parent.get('status') in ('RPD_APPWORLD_A3_SIGNAL_PASS','RPD_APPWORLD_A3_SIGNAL_MODEL_FAIL')};status=parent['status'] if all(checks.values()) else 'RPD_APPWORLD_A3_SIGNAL_PROTOCOL_FAIL';payload={'schema':'recurrent_appworld_a3_contended_analysis_v1','status':status,'checks':checks,'quality_metrics_authoritative':True,'token_counts_authoritative':True,'latency_authoritative':False,'throughput_authoritative':False,'gpu_speedup_authorized':False,'parent_analysis':parent,'hashes':{'addendum':H(apath),'contended_lock':H(lockp),'raw':H(rp),'parent_analysis':H(parentp)},'external_process_actions_taken':False,'headline_eligible':False};out=R(a.output_dir);(out/'contended_analysis.json').write_text(json.dumps(payload,indent=2,sort_keys=True)+'\n');pooled=parent['pooled'];lines=['# AppWorld A3 — Contended Quality-Only Result','',f"## Verdict: **`{status}`**",'',f"- Parse rate: {pooled['parse_rate']:.3f}",f"- Balanced accuracy: {pooled['balanced_accuracy']:.3f}",f"- False-positive rate: {pooled['eta_fp']:.3f}",f"- False-negative rate: {pooled['eta_fn']:.3f}",f"- Pair both-correct rate: {parent['pair_both_correct_rate']:.3f}",f"- Type-cluster bootstrap BA CI95: [{parent['cluster_bootstrap_balanced_accuracy_ci95'][0]:.3f}, {parent['cluster_bootstrap_balanced_accuracy_ci95'][1]:.3f}]",'','## Contention boundary','','- Signal-quality metrics: authoritative for this train anchor','- Token counts: authoritative','- Wall-clock latency and throughput: non-authoritative','- GPU speedup: not authorized','- External process actions: none','', 'This is a train-only pre-commit semantic signal result, not an end-to-end task-completion claim.'];(out/'CONTENDED_RESULTS.md').write_text('\n'.join(lines)+'\n');print(json.dumps({'status':status,'report':str((out/'CONTENDED_RESULTS.md').relative_to(R('.')))}))
